class MeshNodeSchema(BaseModel):
    """Pydantic v2 validated schema for MeshNode deserialization.
    
    Enforces strict typing, value constraints, and cross-field validation
    to prevent type confusion, attribute injection, and data corruption attacks.
    
    Security enhancements:
    - IPv4 octet range validation (0-255)
    - Leading zero rejection (prevents octal interpretation attacks)
    - Reserved address blocking (0.0.0.0/8, 127.0.0.0/8, 169.254.0.0/16)
    - Heartbeat timestamp bounds checking
    """
    
    node_id: str = Field(
        ...,
        min_length=1,
        max_length=128,
        pattern=r'^[a-zA-Z0-9_-]+$',
        description="Unique node identifier (alphanumeric, hyphens, underscores only)"
    )
    name: str = Field(
        ...,
        min_length=1,
        max_length=256,
        description="Human-readable node name"
    )
    role: str = Field(
        ...,
        min_length=1,
        max_length=64,
        description="Node role (e.g., worker, coordinator, gateway)"
    )
    host: str = Field(
        default="127.0.0.1",
        pattern=r'^((25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(25[0-5]|2[0-4]\d|[01]?\d\d?)$|^localhost$',
        description="Valid IPv4 address (each octet 0-255) or 'localhost'"
    )
    port: int = Field(
        default=0,
        ge=0,
        le=65535,
        description="Network port number"
    )
    specialties: List[str] = Field(
        default_factory=list,
        max_length=50,
        description="List of node specialties"
    )
    skills: List[str] = Field(
        default_factory=list,
        max_length=50,
        description="List of node skills"
    )
    hardware: Dict[str, Any] = Field(
        default_factory=dict,
        description="Hardware capabilities dictionary"
    )
    status: str = Field(
        default="online",
        pattern=r'^(online|offline|busy|error)$',
        description="Current node status"
    )
    last_heartbeat: float = Field(
        default_factory=time.time,
        description="Unix timestamp of last heartbeat"
    )
    joined_at: str = Field(
        default_factory=lambda: datetime.now().isoformat(),
        description="ISO 8601 timestamp of node join time"
    )
    task_count: int = Field(
        default=0,
        ge=0,
        description="Number of tasks processed"
    )
    peer_connections: int = Field(
        default=0,
        ge=0,
        description="Number of active peer connections"
    )

    @field_validator('last_heartbeat')
    @classmethod
    def validate_heartbeat_timestamp(cls, v: float) -> float:
        """Ensure heartbeat is a valid Unix timestamp (not future by more than 5 minutes)."""
        now = time.time()
        if v > now + 300:  # Allow 5-minute clock skew
            raise ValueError(f"Heartbeat timestamp {v} is too far in the future (max {now + 300})")
        if v < 946684800:  # Year 2000 minimum
            raise ValueError(f"Heartbeat timestamp {v} is too far in the past (min 946684800)")
        return v

    @field_validator('host')
    @classmethod
    def validate_host_format(cls, v: str) -> str:
        """Comprehensive host validation with octet range checking and security hardening.
        
        Validates:
        1. IPv4 octet ranges (0-255)
        2. No leading zeros (prevents octal interpretation attacks)
        3. Reserved address blocking (0.0.0.0/8, 127.0.0.0/8, 169.254.0.0/16)
        """
        if v == "localhost":
            return v
        
        # Split into octets and validate each one
        octets = v.split('.')
        if len(octets) != 4:
            raise ValueError(f"Invalid IPv4 address format: {v}")
        
        for octet in octets:
            try:
                value = int(octet)
            except ValueError:
                raise ValueError(f"Non-numeric octet in IPv4 address: {octet}")
            
            if not 0 <= value <= 255:
                raise ValueError(f"Octet {octet} out of valid range (0-255)")
            
            # Reject leading zeros (security: some parsers interpret as octal)
            if len(octet) > 1 and octet[0] == '0':
                raise ValueError(f"Leading zeros not allowed in octet: {octet}")
        
        # Validate against private/reserved ranges
        octet_values = [int(x) for x in octets]
        
        # Block 0.0.0.0/8 (current network)
        if octet_values[0] == 0:
            raise ValueError(f"Reserved address range not allowed: {v}")
        
        # Block 127.0.0.0/8 (loopback) - should use 'localhost' instead
        if octet_values[0] == 127:
            raise ValueError(f"Loopback address not allowed (use 'localhost'): {v}")
        
        # Block 169.254.0.0/16 (link-local)
        if octet_values[0] == 169 and octet_values[1] == 254:
            raise ValueError(f"Link-local address not allowed: {v}")
        
        return v


