class MeshNode:
    """Represents a single agent node in the P2P mesh."""
    
    def __init__(self, schema: MeshNodeSchema):
        self.schema = schema
        self._connections: Dict[str, 'MeshNode'] = {}
        self._task_queue: asyncio.Queue = asyncio.Queue()
        self._running = False
        self._heartbeat_task: Optional[asyncio.Task] = None
        
    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'MeshNode':
        """Create a MeshNode from a dictionary with full validation."""
        schema = MeshNodeSchema(**data)
        return cls(schema)
    
    @classmethod
    def from_json(cls, json_str: str) -> 'MeshNode':
        """Create a MeshNode from a JSON string with full validation."""
        data = json.loads(json_str)
        return cls.from_dict(data)
    
    def to_dict(self) -> Dict[str, Any]:
        """Serialize node to dictionary."""
        return self.schema.model_dump()
    
    def to_json(self) -> str:
        """Serialize node to JSON string."""
        return self.schema.model_dump_json()
    
    @property
    def node_id(self) -> str:
        return self.schema.node_id
    
    @property
    def host(self) -> str:
        return self.schema.host
    
    @property
    def port(self) -> int:
        return self.schema.port
    
    @property
    def address(self) -> str:
        """Get the full address (host:port)."""
        return f"{self.host}:{self.port}"
    
    def update_heartbeat(self):
        """Update the heartbeat timestamp."""
        self.schema.last_heartbeat = time.time()
    
    def is_alive(self, timeout: float = 30.0) -> bool:
        """Check if node is still alive based on heartbeat."""
        return (time.time() - self.schema.last_heartbeat) < timeout
    
    async def connect(self, peer: 'MeshNode'):
        """Establish a connection to a peer node."""
        self._connections[peer.node_id] = peer
        self.schema.peer_connections = len(self._connections)
        logger.info(f"Node {self.node_id} connected to peer {peer.node_id}")
    
    async def disconnect(self, peer_id: str):
        """Disconnect from a peer node."""
        if peer_id in self._connections:
            del self._connections[peer_id]
            self.schema.peer_connections = len(self._connections)
            logger.info(f"Node {self.node_id} disconnected from peer {peer_id}")
    
    def get_peers(self) -> List[str]:
        """Get list of connected peer IDs."""
        return list(self._connections.keys())
    
    async def send_task(self, task: Dict[str, Any], target_id: str):
        """Send a task to a specific peer."""
        if target_id not in self._connections:
            raise ValueError(f"Peer {target_id} not connected")
        await self._connections[target_id]._task_queue.put(task)
        self.schema.task_count += 1
    
    async def receive_task(self) -> Dict[str, Any]:
        """Receive a task from the queue (blocking)."""
        return await self._task_queue.get()
    
    async def start_heartbeat(self, interval: float = 5.0):
        """Start sending heartbeat signals."""
        self._running = True
        self._heartbeat_task = asyncio.create_task(self._heartbeat_loop(interval))
    
    async def stop_heartbeat(self):
        """Stop sending heartbeat signals."""
        self._running = False
        if self._heartbeat_task:
            self._heartbeat_task.cancel()
            try:
                await self._heartbeat_task
            except asyncio.CancelledError:
                pass
    
    async def _heartbeat_loop(self, interval: float):
        """Internal heartbeat loop."""
        while self._running:
            self.update_heartbeat()
            await asyncio.sleep(interval)


