class AgentMesh:
    """Manages the P2P agent mesh topology."""
    
    def __init__(self, node_id: str, host: str = "127.0.0.1", port: int = 0):
        self.local_node = MeshNode.from_dict({
            "node_id": node_id,
            "name": f"Agent-{node_id}",
            "role": "worker",
            "host": host,
            "port": port,
            "specialties": [],
            "skills": [],
            "hardware": {},
            "status": "online"
        })
        self._nodes: Dict[str, MeshNode] = {node_id: self.local_node}
        self._running = False
        self._gossip_task: Optional[asyncio.Task] = None
        self._cleanup_task: Optional[asyncio.Task] = None
        self._embedding_skill = FastEmbeddingSkill()
        
    def register_node(self, node_data: Dict[str, Any]) -> MeshNode:
        """Register a new node in the mesh with full validation."""
        node = MeshNode.from_dict(node_data)
        self._nodes[node.node_id] = node
        logger.info(f"Node registered: {node.node_id} at {node.address}")
        return node
    
    def unregister_node(self, node_id: str):
        """Remove a node from the mesh."""
        if node_id in self._nodes and node_id != self.local_node.node_id:
            del self._nodes[node_id]
            logger.info(f"Node unregistered: {node_id}")
    
    def get_node(self, node_id: str) -> Optional[MeshNode]:
        """Get a node by ID."""
        return self._nodes.get(node_id)
    
    def get_all_nodes(self) -> List[MeshNode]:
        """Get all registered nodes."""
        return list(self._nodes.values())
    
    def get_alive_nodes(self, timeout: float = 30.0) -> List[MeshNode]:
        """Get all nodes that are still alive."""
        return [node for node in self._nodes.values() if node.is_alive(timeout)]
    
    def find_nodes_by_skill(self, skill: str) -> List[MeshNode]:
        """Find nodes that have a specific skill."""
        return [
            node for node in self._nodes.values()
            if skill in node.schema.skills
        ]
    
    def find_nodes_by_specialty(self, specialty: str) -> List[MeshNode]:
        """Find nodes that have a specific specialty."""
        return [
            node for node in self._nodes.values()
            if specialty in node.schema.specialties
        ]
    
    def find_nodes_by_role(self, role: str) -> List[MeshNode]:
        """Find nodes with a specific role."""
        return [
            node for node in self._nodes.values()
            if node.schema.role == role
        ]
    
    async def connect_to_peer(self, peer_id: str):
        """Establish connection to a peer node."""
        if peer_id not in self._nodes:
            raise ValueError(f"Peer {peer_id} not found in mesh")
        peer = self._nodes[peer_id]
        await self.local_node.connect(peer)
        await peer.connect(self.local_node)
    
    async def disconnect_from_peer(self, peer_id: str):
        """Disconnect from a peer node."""
        if peer_id in self._nodes:
            peer = self._nodes[peer_id]
            await self.local_node.disconnect(peer_id)
            await peer.disconnect(self.local_node.node_id)
    
    async def route_task(self, task: Dict[str, Any], target_id: str):
        """Route a task to a specific node."""
        if target_id not in self._nodes:
            raise ValueError(f"Target node {target_id} not found in mesh")
        target = self._nodes[target_id]
        await target.send_task(task, self.local_node.node_id)
    
    async def broadcast_task(self, task: Dict[str, Any]):
        """Broadcast a task to all connected peers."""
        for peer_id in self.local_node.get_peers():
            try:
                await self.route_task(task, peer_id)
            except Exception as e:
                logger.error(f"Failed to route task to {peer_id}: {e}")
    
    def save_topology(self, filepath: Optional[str] = None):
        """Save the current mesh topology to disk."""
        if filepath is None:
            filepath = os.path.join(MESH_DIR, f"topology_{self.local_node.node_id}.json")
        
        topology = {
            "timestamp": time.time(),
            "local_node": self.local_node.to_dict(),
            "nodes": {nid: node.to_dict() for nid, node in self._nodes.items()}
        }
        
        with open(filepath, 'w') as f:
            json.dump(topology, f, indent=2)
        
        logger.info(f"Topology saved to {filepath}")
    
    def load_topology(self, filepath: str) -> int:
        """Load mesh topology from disk. Returns number of nodes loaded."""
        with open(filepath, 'r') as f:
            topology = json.load(f)
        
        count = 0
        for nid, node_data in topology.get("nodes", {}).items():
            if nid not in self._nodes:
                self.register_node(node_data)
                count += 1
        
        logger.info(f"Loaded {count} nodes from {filepath}")
        return count
    
    async def start(self, gossip_interval: float = 10.0, cleanup_interval: float = 60.0):
        """Start the mesh manager."""
        self._running = True
        await self.local_node.start_heartbeat()
        self._gossip_task = asyncio.create_task(self._gossip_loop(gossip_interval))
        self._cleanup_task = asyncio.create_task(self._cleanup_loop(cleanup_interval))
        logger.info(f"AgentMesh started for node {self.local_node.node_id}")
    
    async def stop(self):
        """Stop the mesh manager."""
        self._running = False
        await self.local_node.stop_heartbeat()
        
        if self._gossip_task:
            self._gossip_task.cancel()
            try:
                await self._gossip_task
            except asyncio.CancelledError:
                pass
        
        if self._cleanup_task:
            self._cleanup_task.cancel()
            try:
                await self._cleanup_task
            except asyncio.CancelledError:
                pass
        
        self.save_topology()
        logger.info(f"AgentMesh stopped for node {self.local_node.node_id}")
    
    async def _gossip_loop(self, interval: float):
        """Gossip protocol loop for topology dissemination."""
        while self._running:
            try:
                # Simple gossip: share node list with peers
                alive_nodes = self.get_alive_nodes()
                gossip_data = {
                    "type": "topology_update",
                    "sender": self.local_node.node_id,
                    "nodes": {n.node_id: n.to_dict() for n in alive_nodes},
                    "timestamp": time.time()
                }
                
                await self.broadcast_task(gossip_data)
                await asyncio.sleep(interval)
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"Gossip error: {e}")
                await asyncio.sleep(interval)
    
    async def _cleanup_loop(self, interval: float):
        """Cleanup dead nodes from the mesh."""
        while self._running:
            try:
                now = time.time()
                dead_nodes = [
                    nid for nid, node in self._nodes.items()
                    if nid != self.local_node.node_id and 
                    (now - node.schema.last_heartbeat) > 60.0
                ]
                
                for nid in dead_nodes:
                    logger.warning(f"Removing dead node: {nid}")
                    self.unregister_node(nid)
                
                await asyncio.sleep(interval)
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"Cleanup error: {e}")
                await asyncio.sleep(interval)


