def create_node_id() -> str:
    """Generate a unique node ID."""
    timestamp = str(time.time()).encode()
    return hashlib.sha256(timestamp).hexdigest()[:16]


def discover_peers(mesh_dir: str = MESH_DIR) -> List[Dict[str, Any]]:
    """Discover peer nodes from saved topology files."""
    peers = []
    if not os.path.exists(mesh_dir):
        return peers
    
    for filename in os.listdir(mesh_dir):
        if filename.startswith("topology_") and filename.endswith(".json"):
            filepath = os.path.join(mesh_dir, filename)
            try:
                with open(filepath, 'r') as f:
                    topology = json.load(f)
                local_node = topology.get("local_node", {})
                if local_node:
                    peers.append(local_node)
            except (json.JSONDecodeError, IOError) as e:
                logger.error(f"Failed to read topology file {filepath}: {e}")
    
    return peers


